import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"セッションのコンテキスト圧縮","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/compaction.md","filePath":"ja/guides/compaction.md","lastUpdated":1792323081000}'),n={name:"ja/guides/compaction.md"};function d(s,t,i,l,c,h){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="セッションのコンテキスト圧縮" tabindex="-1">セッションのコンテキスト圧縮 <a class="header-anchor" href="#セッションのコンテキスト圧縮" aria-label="Permalink to &quot;セッションのコンテキスト圧縮&quot;">​</a></h1><p><strong>コンテキスト圧縮</strong>が対象にするのは<strong>現在のこの 1 セッション</strong>だけです: 早い段階の turn を要約に圧縮して、以降のモデル呼び出しが運ぶ<strong>アクティブウィンドウ</strong>を小さく保ちます。</p><p>これは<strong>メモリストアに保存された長期の記憶を書き換えること</strong>とは別物です。保存されたエントリをいじりたい場合は、<a href="./memory.html">長期メモリ</a> を見てください。</p><hr><h2 id="いまはデフォルトで有効、設定ゼロ" tabindex="-1">いまはデフォルトで有効、設定ゼロ <a class="header-anchor" href="#いまはデフォルトで有効、設定ゼロ" aria-label="Permalink to &quot;いまはデフォルトで有効、設定ゼロ&quot;">​</a></h2><p>新しく作った Bot では自動圧縮が<strong>デフォルトで有効</strong>です。しきい値も、圧縮率も、要約モデルも、何ひとつ設定する必要はありません——Memoh はすべてをチャットモデルの <code>context_window</code> に対する比率で決めます:</p><ul><li>セッションの圧縮可能な履歴がウィンドウの約 <strong>50%</strong> を超えたら: その turn の終了後に<strong>バックグラウンド</strong>で圧縮します。</li><li>バックグラウンドが追いつかず、約 <strong>75%</strong> を超えてしまったら: 次の turn を送る前に<strong>同期的に</strong>圧縮します。</li><li>どちらの経路でも、生の履歴をウィンドウの約 <strong>40%</strong> まで戻すことを目指します。</li></ul><p>唯一の本当の前提条件: チャットモデルがモデル設定で <code>context_window</code> を宣言していることです。これがないと、自動ポリシーには予算の基準がなく、<strong>決してトリガーされません</strong>。<a href="./../integrations/providers/llm.html">モデルプロバイダーとモデル</a> を見てください。</p><p>このデフォルトが変わる前に作られた Bot は、元の設定を保持し、元の意味のまま動きます（下記の legacy モードを参照）。</p><hr><h2 id="設定項目" tabindex="-1">設定項目 <a class="header-anchor" href="#設定項目" aria-label="Permalink to &quot;設定項目&quot;">​</a></h2><p>調整したければ、今でも調整できます:</p><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>Compaction Enabled</strong></td><td>デフォルトでオン。オフにすると、この Bot の自動圧縮が無効になります。</td></tr><tr><td><strong>Compaction Threshold</strong></td><td>入力 token のしきい値。<code>0</code>（デフォルト）= 上記の自動比率ポリシー。<strong>0 より大きい値</strong>にすると legacy の絶対しきい値モードに切り替わります。</td></tr><tr><td><strong>Compaction Ratio</strong></td><td>どれだけ強く圧縮するか。legacy モードでだけ有効です——しきい値が <code>0</code> のときは、このフィールド自体が非表示になります。</td></tr><tr><td><strong>Compaction Model</strong></td><td>任意の専用要約モデル。デフォルトはチャットモデルを継承します。override を設定した後でも <strong>Use chat model (default)</strong> に戻せます。</td></tr></tbody></table><h3 id="要約モデルの選び方" tabindex="-1">要約モデルの選び方 <a class="header-anchor" href="#要約モデルの選び方" aria-label="Permalink to &quot;要約モデルの選び方&quot;">​</a></h3><p>有効化されている chat モデルならほとんど使えます。唯一の制限は、provider が出力 token の上限を尊重すること。<strong>OpenAI Codex 系モデルは要約モデルにできません</strong>——ドロップダウンの時点で除外されています。</p><p>注意が必要なケース: Bot のメインのチャットモデル自体が Codex のとき、継承できる正当なモデルがないため、自動圧縮は<strong>何も言わずに動かなくなります</strong>。この場合は、Compaction Model を明示的に設定してください。</p><hr><h2 id="いますぐ圧縮する" tabindex="-1">いますぐ圧縮する <a class="header-anchor" href="#いますぐ圧縮する" aria-label="Permalink to &quot;いますぐ圧縮する&quot;">​</a></h2><p>方法は 2 つあります:</p><h3 id="ステータスパネルから" tabindex="-1">ステータスパネルから <a class="header-anchor" href="#ステータスパネルから" aria-label="Permalink to &quot;ステータスパネルから&quot;">​</a></h3><ol><li>現在の会話を開きます。</li><li>セッションのステータスパネルを開きます。</li><li><strong>Compact Now</strong> をクリックします。</li></ol><p>パネルにはコンテキスト使用量、キャッシュ、スキルなども表示されるので、いま圧縮すべきかどうかの判断に役立ちます。</p><h3 id="スラッシュコマンドから" tabindex="-1">スラッシュコマンドから <a class="header-anchor" href="#スラッシュコマンドから" aria-label="Permalink to &quot;スラッシュコマンドから&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact</span></span></code></pre></div><p>または</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact run</span></span></code></pre></div><p>手動の圧縮はできる限り<strong>全量</strong>を圧縮し（自動のターゲットラインで止まりません）、自動圧縮が失敗した後の短いクールダウンもバイパスします。</p><hr><h2 id="圧縮の忠実度" tabindex="-1">圧縮の忠実度 <a class="header-anchor" href="#圧縮の忠実度" aria-label="Permalink to &quot;圧縮の忠実度&quot;">​</a></h2><p>要約器は型付きのセッションレコード単位で動きます。品質に実際に効いてくる挙動は次のとおりです:</p><ul><li>ツール呼び出しとその結果は<strong>決して切り離されません</strong>——1 回の tool のやり取りは、丸ごと生の履歴に残るか、丸ごと要約に入るかのどちらかです。</li><li>メディアは <code>[image]</code> / <code>[file]</code> マーカーに縮退し、生データは詰め込みません。</li><li>空の要約、途中で切れた要約、元より小さくならなかった要約はそのまま却下され、結果として保存されません。</li><li>複数のワークスペースをまたぐセッションでは、「どの発言がどのマシンで起きたか」という情報を要約が保持します。</li></ul><p>通常の chat、<strong>discuss</strong>、pipeline 系の会話はすべて圧縮の対象です。</p><hr><h2 id="記録" tabindex="-1">記録 <a class="header-anchor" href="#記録" aria-label="Permalink to &quot;記録&quot;">​</a></h2><p>Bot 詳細の <strong>圧縮</strong> タブで各回の記録を確認できます: 成功／失敗、要約またはプレビュー、関係したメッセージ数、開始・終了時刻、あればモデルと使用量。<strong>自動</strong>が実際に動いているかの確認や、失敗原因の調査に使ってください。</p><h3 id="よくある失敗原因" tabindex="-1">よくある失敗原因 <a class="header-anchor" href="#よくある失敗原因" aria-label="Permalink to &quot;よくある失敗原因&quot;">​</a></h3><p>実行できないときは <code>compaction.model_unavailable</code> が具体的な理由とともに報告されます: 要約モデルが未設定、chat モデルではない、無効化されている、provider が無効化されている、provider が出力上限をサポートしない（Codex）、モデルに既知の context window がない。<code>/compact</code> もチャット内で同じ状態を報告します。</p><hr><h2 id="context-window-との関係" tabindex="-1"><code>context_window</code> との関係 <a class="header-anchor" href="#context-window-との関係" aria-label="Permalink to &quot;`context_window` との関係&quot;">​</a></h2><p>Memoh は現在の chat モデルの <code>context_window</code> をこのセッションと突き合わせます。上限にどれだけ近いかは、Web のステータスパネルでも <code>/status</code> でも見られます。token は粗い見積もり（約 4 文字 / token）なので、パーセンテージは目安として扱い、正確な値だとは思わないでください。</p><hr><h2 id="「メモリ圧縮」との違い" tabindex="-1">「メモリ圧縮」との違い <a class="header-anchor" href="#「メモリ圧縮」との違い" aria-label="Permalink to &quot;「メモリ圧縮」との違い&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>対象範囲</th><th>トリガー</th><th>結果</th></tr></thead><tbody><tr><td><strong>コンテキスト圧縮</strong></td><td>現在のアクティブセッション</td><td>自動 / ステータスパネル / <code>/compact</code></td><td>このセッション内の古い内容が要約になり、以降の turn を続けやすくなる</td></tr><tr><td><strong>メモリ圧縮</strong></td><td>長期メモリプロバイダー</td><td>メモリタブ</td><td>ストア内のメモリエントリを書き換える。単一セッションの prompt ではない</td></tr></tbody></table><p><strong>1 つの会話が長くなりすぎた</strong> → コンテキスト圧縮。<br><strong>保存された記憶がノイズだらけで重い</strong> → メモリ側でその種のメンテナンスを行ってください。</p><hr><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><ul><li>セッション、Discuss: <a href="./sessions.html">セッション</a></li><li>スラッシュコマンドと <code>/compact</code>: <a href="./slash-commands.html">スラッシュコマンド</a></li><li>長期メモリのメンテナンス: <a href="./memory.html">長期メモリ</a></li></ul>',47)])])}const m=o(n,[["render",d]]);export{g as __pageData,m as default};
